Import ListNotations.
Open Scope bv_scope.
Unset Lia Cache. Unset Nia Cache. Unset Nra Cache.

Abbreviation SEGS := Plain.M.loaded_segments.
Definition PC_pixRotateOrth : Z := 0x87798.

Section RotOrth.
Context {fx : FPState}.
Variable rom : word -> option byte.

  (* [comment removed for export] *)
  Lemma ro_q1 : forall regs m (pixs : Z), (1 <= pixs < 2 ^ 64)%Z ->
    getr regs 10 = Z_to_bv 64 pixs -> getr regs 11 = Z_to_bv 64 1 ->
    exists regs',
      msteps SEGS (mkst regs (0x87798 : word) m rom) (mkst regs' (0x87840 : word) m rom)
      /\ getr regs' 10 = Z_to_bv 64 pixs /\ getr regs' 11 = Z_to_bv 64 1
      /\ regs_agree (fun r => In r [10; 11; 12]%list) regs regs'.
Proof.
